import{_ as a,o as n,c as o,a0 as t}from"./chunks/framework.BPYRhTv9.js";const u=JSON.parse('{"title":"Known Issues","description":"","frontmatter":{"title":"Known Issues"},"headers":[],"relativePath":"reference/acknowledgements.md","filePath":"reference/acknowledgements.md"}'),i={name:"reference/acknowledgements.md"};function s(r,e,l,d,c,h){return n(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="known-issues" tabindex="-1">Known Issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known Issues&quot;">​</a></h1><p>These are bugs and behavior gaps we know about. We list them here because hiding a known issue is worse than naming it.</p><h3 id="voice-attached-downloads-may-not-play-on-mac-and-iphone" tabindex="-1">Voice-attached downloads may not play on Mac and iPhone <a class="header-anchor" href="#voice-attached-downloads-may-not-play-on-mac-and-iphone" aria-label="Permalink to &quot;Voice-attached downloads may not play on Mac and iPhone&quot;">​</a></h3><p>Voice-attached cards use the WebM format, which Apple&#39;s QuickTime and iOS Photos app do not play natively. On Android and Windows the file opens in the default media player. The shared web preview plays the voice in any modern browser, including on Apple devices.</p><p><strong>Workaround:</strong> Open the card via the share link on Apple devices, or download on a non-Apple device first.</p><h3 id="voice-is-lost-on-png-download-share-link-voice-upload-can-silently-fail" tabindex="-1">Voice is lost on PNG download; share link voice upload can silently fail <a class="header-anchor" href="#voice-is-lost-on-png-download-share-link-voice-upload-can-silently-fail" aria-label="Permalink to &quot;Voice is lost on PNG download; share link voice upload can silently fail&quot;">​</a></h3><p>Two related issues. PNG images cannot contain audio, so downloading as PNG loses the voice. When creating a share link, the image uploads first and success is reported immediately — the voice upload runs in the background and can fail silently (network drop, oversized file, server hiccup) without warning.</p><p><strong>Workaround:</strong> For voice, download the WebM file or use the share link. Verify the voice plays in the preview before sending a share link. The image is always present.</p><h3 id="firefox-cannot-record-voice" tabindex="-1">Firefox cannot record voice <a class="header-anchor" href="#firefox-cannot-record-voice" aria-label="Permalink to &quot;Firefox cannot record voice&quot;">​</a></h3><p>Firefox does not support the Web Speech API that powers real-time transcription during recording. Chrome, Edge, Safari, and most mobile browsers support it. In Firefox, you can still type your message directly into the text box.</p><p><strong>Workaround:</strong> Use Chrome, Edge, or Safari for voice recording. Or type your message in Firefox.</p><h3 id="parts-of-the-interface-are-still-in-english-in-ten-of-eleven-languages" tabindex="-1">Parts of the interface are still in English in ten of eleven languages <a class="header-anchor" href="#parts-of-the-interface-are-still-in-english-in-ten-of-eleven-languages" aria-label="Permalink to &quot;Parts of the interface are still in English in ten of eleven languages&quot;">​</a></h3><p>Eleven languages are supported for the card interface, but only English is fully translated. The other ten languages fall back to English for some buttons and messages. The card text itself renders correctly in all languages.</p><p><strong>Workaround:</strong> Use the app in English for the most complete experience. We plan to complete translations in a future update.</p><hr><p><sup>Wibe Stories</sup><br><sup>© 2026 YGLabs</sup></p>',16)])])}const f=a(i,[["render",s]]);export{u as __pageData,f as default};
